import { Router } from "express";
import { analytics } from "../controllers/analytics.controller.js";
import { generateCertificate, myCertificates, verifyCertificate } from "../controllers/certificate.controller.js";
import { createDiscussion, deleteDiscussion, listDiscussions, replyDiscussion } from "../controllers/discussion.controller.js";
import { markRead, myNotifications } from "../controllers/notification.controller.js";
import { createPayment, listPayments, myPayments } from "../controllers/payment.controller.js";
import { deleteReview, listReviews, upsertReview } from "../controllers/review.controller.js";
import { getSettings, updateSettings } from "../controllers/settings.controller.js";
import { authenticate } from "../middlewares/auth.js";
import { authorize } from "../middlewares/roles.js";
import { asyncHandler } from "../utils/asyncHandler.js";
export const miscRoutes = Router();
miscRoutes.get("/certificates/verify/:certificateCode", asyncHandler(verifyCertificate));
miscRoutes.get("/settings", asyncHandler(getSettings));
miscRoutes.use(authenticate);
miscRoutes.post("/payments", asyncHandler(createPayment));
miscRoutes.get("/payments/my", asyncHandler(myPayments));
miscRoutes.get("/payments", authorize("SUPER_ADMIN", "ADMIN"), asyncHandler(listPayments));
miscRoutes.get("/certificates/my-certificates", asyncHandler(myCertificates));
miscRoutes.post("/certificates/generate", asyncHandler(generateCertificate));
miscRoutes.get("/reviews", asyncHandler(listReviews));
miscRoutes.post("/reviews", authorize("STUDENT"), asyncHandler(upsertReview));
miscRoutes.delete("/reviews/:id", asyncHandler(deleteReview));
miscRoutes.get("/notifications", asyncHandler(myNotifications));
miscRoutes.patch("/notifications/:id/read", asyncHandler(markRead));
miscRoutes.get("/discussions/course/:courseId", asyncHandler(listDiscussions));
miscRoutes.post("/discussions", asyncHandler(createDiscussion));
miscRoutes.post("/discussions/:id/replies", asyncHandler(replyDiscussion));
miscRoutes.delete("/discussions/:id", asyncHandler(deleteDiscussion));
miscRoutes.put("/settings", authorize("SUPER_ADMIN", "ADMIN"), asyncHandler(updateSettings));
miscRoutes.get("/analytics", authorize("SUPER_ADMIN", "ADMIN", "INSTRUCTOR"), asyncHandler(analytics));
